impl Solution {
    pub fn min_moves(target: i32, max_doubles: i32) -> i32 {
        if target <= 1 {
            0
        } else if max_doubles <= 0 {
            target - 1
        } else if target % 2 == 0 {
            1 + Solution::min_moves(target / 2, max_doubles - 1)
        } else {
            1 + Solution::min_moves(target - 1, max_doubles)
        }
    }
}

